const STOCK_DICT: StockDictItem[] = [...CHUNK_0, ...CHUNK_1, ...CHUNK_2, ...CHUNK_3, ...CHUNK_4, ...CHUNK_5, ...CHUNK_6, ...CHUNK_7, ...CHUNK_8]

// 单一数据源：四交易所全量合并（去重并排序）
const ALL_STOCKS: StockDictItem[] = [
  ...STOCK_DICT,
]

export default ALL_STOCKS

/**
 * 按股票代码快速查找（支持带交易所后缀的代码如 600519.SH）
 */
export function findStockBySymbol(symbol: string): StockDictItem | undefined {
  const normalized = symbol.replace(/\.(SH|SZ|BJ|HK)$/i, '').trim().toUpperCase()
  return ALL_STOCKS.find((s) => s.symbol === normalized)
}

/**
 * 获取股票的市场代码（用于构造交易所代码）
 */
export function toExchangeSymbol(symbol: string, market: 'SH' | 'SZ' | 'BJ' | 'HK'): string {
  if (market === 'HK') return symbol
  const prefix = market === 'SH' ? 'sh' : market === 'SZ' ? 'sz' : 'bj'
  return `${prefix}${symbol}`
}
